Specify a `.svg` extension in the output path to save as SVG:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
import { dot, plot } from "@observablehq/plot";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// We load data from an array
const data = [{ year: 2024, value: 10 }, { year: 2025, value: 15 }];
await table.loadArray(data);
// We define a chart function
const chartFunction = (plotData: unknown[]) =>
  plot({
    marks: [
      dot(plotData, { x: "year", y: "value" }),
    ],
  });
// We write the chart as SVG
await table.writeChart(
  chartFunction,
  "./output/chart.svg"
);
// We close everything
await sdb.done();
```

