Use method: 'spheroid' and unit: 'km' for accurate distance in kilometers with EPSG:4326 data.
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// We load geospatial data from a file
await table.loadGeoData("./geodata.geojson");
// Compute Spheroid distance in kilometers
await table.distance("area1", "area2", "distance_spheroid_km", {
  method: "spheroid",
  unit: "km"
});
// Log the first rows
