You can use the `style` option in the `writeMap` method to apply custom CSS to the map. Here's an example:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
import { geo, plot } from "@observablehq/plot";

const sdb = new SimpleDB();
const table = sdb.newTable();
await table.loadGeoData("./my-geodata.geojson");

const mapFunction = (geoJsonData: { features: unknown[] }) =>
  plot({
    projection: {
      type: "conic-conformal",
      rotate: [100, -60],
      domain: geoJsonData,
    },
    marks: [
      geo(geoJsonData, { stroke: "black", fill: "lightblue" }),
    ],
  });

const outputPath = "./output/map.png";
const options = { style: "#chart { background-color: black; }" };

await table.writeMap(mapFunction, outputPath, options);
await sdb.done();
```

