  { date: new Date("2023-01-01"), value: 10.5 },
  { date: new Date("2023-02-01"), value: 20.75 },
  { date: new Date("2023-03-01"), value: 30.25 },
  { date: new Date("2023-04-01"), value: 40.9 },
];
await table.loadArray(data);
// Convert the date column to a string for display
await table.convert({ date: "string" }, { datetimeFormat: "%x" });
// Format the x-axis to show month and day (e.g., "Jan 01") and y-axis to two decimal places
await table.logLineChart("date", "value", {
  formatX: (d) => {
    const dateStr = d as string;
    const [month, day] = dateStr.split('/');
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return `${monthNames[parseInt(month, 10) - 1]} ${day}`;
  },
  formatY: (d) => d.toFixed(2),
});
// We close everything
await sdb.done();
```

