Here's how you can increment a numeric column by 1 using `updateWithJS`:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load data from a CSV file (assuming it has a column 'column1')
await table.loadData("./data.csv");
// Update the 'column1' column: increment numeric values by 1, set non-numeric to null
await table.updateWithJS((rows) => {
  const modifiedRows = rows.map((d) => ({
    ...d,
    column1: typeof d.column1 === "number" ? d.column1 + 1 : null,
  }));
  return modifiedRows;
});
// Log the first rows to see the updated data
await table.logTable();
// We close everything
await sdb.done();
```

