// Clone tableA with custom name, filtered rows, and specific columns
const tableB = await tableA.cloneTable({
  outputTable: "filtered_cloned_table",
  conditions: "age >= 18 AND country = 'USA'",
  columns: ["name", "email", "age", "country"]
});
