import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We execute a query to create a new table (without returning data)
await sdb.customQuery(
  "CREATE TABLE young_employees AS SELECT * FROM employees WHERE age > 30"
);
// We close everything
await sdb.done();
```

The method will throw an error if the specified columns do not exist. Here's an example:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable("myTable");
// Assume the data has no 'invalid_lat' or 'invalid_lon' columns
await table.loadData("./data.csv");
try {
  // This will throw an error because the columns do not exist
  await table.points("invalid_lat", "invalid_lon", "geom");
} catch (error) {
  console.error("Error creating points:", error);
}
// We close everything
await sdb.done();
```

Calling unnestGeo on an empty table will simply resolve the promise without modifying the table. It’s safe to call, but you’ll see no changes:
```
// We start a SimpleDB instance
import { SimpleDB } from "@nshiab/simple-data-analysis";
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// No data loaded
await table.unnestGeo(); // resolves immediately
// Log the table (will be empty)
await table.logTable();
// We close everything
await sdb.done();
```

