import { SimpleDB } from '@nshiab/simple-data-analysis';
import { dot, plot } from '@observablehq/plot';
const sdb = new SimpleDB();
const table = sdb.newTable();
await table.loadArray([{ year: 2024, value: 10 }, { year: 2025, value: 15 }]);

const chartFunction = (data) =>
  plot({
    marks: [
      dot(data, { x: 'year', y: 'value' }),
    ],
  });

await table.writeChart(chartFunction, './output/chart-dark.png', {
  dark: true,
});
await table.logTable();
await sdb.done();
```

Calling removeColumns will permanently remove the specified columns from your table. Here's an example:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Let's assume we have some data loaded into the table
await table.loadData("./data.csv");
// Remove 'unnecessaryColumn' from the table
await table.removeColumns("unnecessaryColumn");
// Log the updated table to see the changes
await table.logTable();
// We close everything
await sdb.done();
```

