import { SimpleDB } from "@nshiab/simple-data-analysis";
const sdb = new SimpleDB();
const table = sdb.newTable();
await table.loadData("./data.csv");
// Replace "kilograms" with "kg" and "liters" with "l" in both "weight" and "volume" columns
await table.replace(["weight", "volume"], {
  "kilograms": "kg",
  "liters": "l"
});
await table.logTable();
await sdb.done();
```

The `returnDataFrom` option controls whether the query results are returned. If set to `"query"`, the results are returned as an array of objects. If set to `"none"` (the default), the query is executed, but no results are returned.
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// Execute a query without returning data
await sdb.customQuery(
  "SELECT * FROM my_table",
  { returnDataFrom: "none" },
);
// Execute a query and return the results
const results = await sdb.customQuery(
  "SELECT * FROM my_table",
  { returnDataFrom: "query" },
);
console.log(results);
// We close everything
await sdb.done();
```

